    # --- Juge isolé des forks (miniz-0031) ---

    def judged_contribution(self, suspects=(), outputs=914, author="alice", extra_judge=None):
        cid = self.submit_0099(author=author)
        verdict = self.dir / "verdict.json"
        judge = {"version": 1, "seed": "ab" * 16, "outputs_compared": outputs, "suspicious_constructs": list(suspects)}
        judge.update(extra_judge or {})
        verdict.write_text(json.dumps({"ci": "green", "gain": 0.05, "beyond_noise": True, "instructions": INSTRUCTIONS_N6,
                                       "changed_lines": 10, "judge": judge}), encoding="utf-8")
        self.assertEqual(self.bee("record-verdict", cid, "--verdict", str(verdict), "--sha", "abc1234",
                                  "--files", self.pr_files())[0], 0)
        for reviewer in ("bruno", "chloe"):
            if reviewer != author:
                self.assertEqual(self.bee("review", cid, *self.read_value(cid), "--user", reviewer, "--opinion", "favorable",
                                          "--reason", "Relu, rien à signaler ici.")[0], 0)
        if author != "bidji29":
            self.assertEqual(self.bee("vote", cid, "--user", "bidji29", "--value", "1")[0], 0)
        os.environ["BEE_NOW"] = "2026-10-29T12:00:00Z"
        return cid

    def set_gate(self, value):
        path = self.dir / "bee.yaml"
        text = path.read_text(encoding="utf-8")
        path.write_text(text.replace("guardian_review_required: true", f"guardian_review_required: {value}"), encoding="utf-8")

