ZONE_NODE = """---
parent: projects/lossless-compression/miniz
updated_on: "2026-10-30"
maintained_by: ruche-0010
line_budget: 40
---
# Décompression (tinfl)
## Pourquoi cette branche existe
tinfl_decompress fait l'essentiel de la décompression.
## Ce qui compte ici
La sortie reste identique ; les lectures non alignées passent par memcpy.
## Ce qu'on peut ignorer ici
La compression.
## Enfants
Aucun.
"""


class TestTree(BaseTest):
    """L'arbre du sens (docs/tree.md) : bee validate tient les nœuds et le rattachement des tâches ; bee context imprime
    le chemin d'une tâche."""

    def node(self, identifier):
        return self.dir / bee.node_file(identifier)

    def replace_with(self, identifier, before, after):
        path = self.node(identifier)
        text = path.read_text(encoding="utf-8")
        self.assertIn(before, text)
        path.write_text(text.replace(before, after, 1), encoding="utf-8")

    def refuse(self, *chunks):
        code, text = self.bee("validate")
        self.assertEqual(code, 1, text)
        for m in chunks:
            self.assertIn(m, text)
        return text

    def add_zone(self):
        folder = self.node("projects/lossless-compression/miniz").parent / "tinfl"
        folder.mkdir()
        (folder / "MEANING.md").write_text(ZONE_NODE, encoding="utf-8")
        self.replace_with("projects/lossless-compression/miniz", "## Children\n",
                       "## Children\n- `projects/lossless-compression/miniz/tinfl`: decompression\n")

    def test_delivered_tree_valid_and_tasks_attached(self):
        self.valid_one()
        reg = bee.Registry(self.dir)
        self.assertEqual(bee.task_node(reg, reg.task("miniz-0012")[1]), "projects/lossless-compression/miniz")
        self.assertEqual(bee.task_node(reg, reg.task("libyaml-0010")[1]), "projects/parsing-serialization/libyaml")
        self.assertEqual(bee.task_role(reg.task("miniz-0012")[1]), "optimize")
        self.assertEqual(bee.task_role(reg.task("miniz-0002")[1]), "review")
        self.assertEqual(bee.task_role(reg.task("miniz-0003")[1]), "measure")
        nodes = bee.load_tree(reg)["nodes"]
        self.assertEqual({n for n in nodes if n.startswith("roles/")},
                         {f"roles/{r}" for r in ("optimize", "review", "measure", "debate", "guard", "propose", "invite")})
        self.assertTrue(bee.matches("tree/roles/review/MEANING.md", bee.TOOLING_PATHS),
                        "l'arbre est de l'outillage : PR ordinaire, jamais fusionnée automatiquement")

    def test_node_over_budget(self):
        self.replace_with("roles/review", "## Children\n", "## Children\n" + "".join(f"- ligne {i}\n" for i in range(10)))
        self.refuse("tree/roles/review/MEANING.md: over budget")

    def test_budget_wider_than_the_cap(self):
        self.replace_with("roles/review", "line_budget: 40", "line_budget: 80")
        self.refuse("line_budget « 80 »")
        self.replace_with("roles/review", "line_budget: 80", "line_budget: 10")
        self.refuse("over budget", "budget of 10")

    def test_invisible_character_refused(self):
        self.replace_with("roles/review", "## Children\nNone.", "## Children\nNone.\u200b")
