    def test_short_reasons_without_hidden_character(self):
        """Tour 2 (farid) : le motif d'une relecture n'avait aucun plafond, contrairement aux notes ; ni ceux d'un vote ou
        d'une mesure. Ils suivent maintenant notes.text_max, et rien n'y est caché."""
        cid = self.submit_0099()
        self.commit("submission")
        long = "Relu en entier. " + "x" * 1500
        self.assertIn("reason: 1516 characters, at most 1500", self.bee("review", cid, *self.read_value(cid), "--user", "chloe", "--opinion",
                                                                           "favorable", "--reason", long)[1])
        self.assertIn("invisible character", self.bee("vote", cid, "--user", "chloe", "--value", "1", "--reason",
                                                      "Utile.‮")[1])
        for reason, expected in ((long, "at most 1500"), ("Relu en entier.​", "invisible character")):
            git(self.dir, "switch", "-qC", "review", "main")
            path = self.dir / f"contributions/miniz/{cid}.yaml"
            rec = bee.read_yaml(path)
            rec["reviews"] = [{"reviewer": "chloe", "opinion": "favorable", "reason": reason, "at": os.environ["BEE_NOW"]}]
            bee.write_yaml(path, rec)
            self.commit()
            code, text = self.verify("chloe", "--auto-merge")
            self.assertEqual(code, 1, text)
            self.assertIn(expected, text)
            git(self.dir, "switch", "-qC", "vote", "main")
            bee.write_yaml(self.dir / "votes" / cid / "chloe.yaml",
                            {"voter": "chloe", "subject": cid, "value": 1, "reason": reason, "at": os.environ["BEE_NOW"]})
            self.commit()
            code, text = self.verify("chloe", "--auto-merge")
            self.assertEqual(code, 1, text)
            self.assertIn(expected, text)
        git(self.dir, "switch", "-q", "main")

