    # --- ruche-0041: a fork PR serves one contribution, in whatever form its address is written ---

    SAME_PR = ("https://github.com/Bee-ruche/minizBee/pull/99041", "https://github.com/bee-ruche/minizbee/pull/99041",
               "https://github.com/BEE-RUCHE/MINIZBEE/pull/99041", "https://github.com/bEE-rUCHE/MinizBEE/pull/099041",
               "https://github.com/Bee-ruche/minizBee/pull/000099041")
    OTHER_PRS = ("https://github.com/Bee-ruche/minizBee/pull/99042", "https://github.com/Bee-ruche/minizBee/pull/9904",
                 "https://github.com/Bee-ruche/minizBee/pull/990410", "https://github.com/Bee-ruche/minizBee/pull/990041")
    TOO_LONG = ("https://github.com/Bee-ruche/minizBee/pull/" + "9" * 10, "https://github.com/Bee-ruche/minizBee/pull/" + "9" * 5000)

    def submit_with_pr(self, task, address):
        """bee submit on `tache` with an unused PR, then `adresse` written in place of it, the rest of the file unchanged."""
        code, text = self.bee("submit", task, "--user", "alice", "--pr", "https://github.com/Bee-ruche/minizBee/pull/99049")
        self.assertEqual(code, 0, text)
        path = self.dir / f"contributions/miniz/{task}-c1.yaml"
        bee.write_yaml(path, {**bee.read_yaml(path), "pr": address})

    def test_canonical_pr(self):
        """Owner and repository in lower case, the number (1 to 9 digits) without leading zeros; a value that is not entirely
        a PR address has none."""
        self.assertEqual({bee.canonical_pr(a) for a in self.SAME_PR}, {("bee-ruche", "minizbee", "99041")})
        self.assertEqual(bee.canonical_pr(PR_MINIZ + "0" * 9), ("bee-ruche", "minizbee", "0"))
        self.assertEqual(bee.canonical_pr(PR_MINIZ + "9" * 9), ("bee-ruche", "minizbee", "9" * 9))
        others = [self.SAME_PR[0], *self.OTHER_PRS, "https://github.com/Bee-ruche/libyamlBee/pull/99041",
                  "https://github.com/Bee-ruche2/minizBee/pull/99041"]
        self.assertEqual(len({bee.canonical_pr(a) for a in others}), len(others))
        pr = self.SAME_PR[0]
        for address in (pr + "\n", pr + "/", pr + "/files", pr + "#a", " " + pr, pr.replace("https:", "http:"),
                        pr.replace("github.com", "www.github.com"), pr.replace("github.com", "GitHub.com"),
                        pr.replace("/pull/", "/pulls/"), pr.replace("99041", "٩٩٠٤١"), pr.replace("99041", ""), *self.TOO_LONG,
                        None, 99041, [pr]):
            with self.subTest(address=address):
                self.assertIsNone(bee.canonical_pr(address))

    def test_submit_refuses_a_pr_already_declared(self):
        """bee submit refuses a PR that another contribution declares, in each written form, and a value that is not a PR
        address; it stores another PR in canonical form: the project's fork as written, /pull/, the number without leading
        zeros."""
        self.reserve_on_main("miniz-0099", "miniz-9001")
        self.assertEqual(self.bee("submit", "miniz-0099", "--user", "alice", "--pr", self.SAME_PR[0])[0], 0)
        self.commit("c1")
        case_of = ([(a, 1, "PR " + a + " is already linked to miniz-0099-c1") for a in self.SAME_PR] + [(a, 0, a) for a in self.OTHER_PRS]
               + [("https://github.com/bee-ruche/MINIZBEE/pull/0099043", 0, "https://github.com/Bee-ruche/minizBee/pull/99043")]
               + [(a, 1, "invalid PR address") for a in self.TOO_LONG])
        for address, expected, chunk in case_of:
            with self.subTest(address=address):
                git(self.dir, "reset", "-q", "--hard")
                git(self.dir, "clean", "-fdq")
                code, text = self.bee("submit", "miniz-9001", "--user", "alice", "--pr", address)
                self.assertEqual(code, expected, text)
                self.assertNotIn("Traceback", text)
                path = self.dir / "contributions/miniz/miniz-9001-c1.yaml"
                if expected:
                    self.assertIn(chunk, text)
                    self.assertFalse(path.exists())
                else:
                    self.assertEqual(bee.read_yaml(path)["pr"], chunk)
                    self.valid_one()

    def test_check_pr_and_validate_one_pr_per_contribution(self):
        """bee check-pr and bee validate refuse a second contribution declaring the same PR, in each written form, whether
        the first is on main (in canonical form or not) or in the same PR, and check_pr finds it by itself; a different PR
        passes; an address not in canonical form, or a value that is not a PR address, is refused."""
        self.reserve_on_main("miniz-0099", "miniz-9001")
        git(self.dir, "switch", "-qc", "c1")
        self.assertEqual(self.bee("submit", "miniz-0099", "--user", "alice", "--pr", self.SAME_PR[0])[0], 0)
        self.commit("c1")
        git(self.dir, "switch", "-qc", "c1-autre")
        path = self.dir / "contributions/miniz/miniz-0099-c1.yaml"
        bee.write_yaml(path, {**bee.read_yaml(path), "pr": self.SAME_PR[3]})
        self.commit("c1, another form")
        case_of = ([("main", a) for a in self.SAME_PR + self.OTHER_PRS] + [("c1-autre", a) for a in self.SAME_PR[:3]]
               + [("c1", a) for a in self.SAME_PR + self.OTHER_PRS + (self.SAME_PR[1] + "\n", *self.TOO_LONG)])
        written_one = "the PR address is written https://github.com/Bee-ruche/minizBee/pull/99041"
        for base, address in case_of:
            with self.subTest(base=base, address=address):
                git(self.dir, "switch", "-qfC", "seconde", "c1-autre" if base == "c1-autre" else "c1")
                git(self.dir, "clean", "-fdq")
                if base == "main":  # both contributions in the PR
                    git(self.dir, "reset", "-q", "--soft", "main")
                self.submit_with_pr("miniz-9001", address)
                self.commit()
                code, text = self.bee("check-pr", "--base", base, "--head", "HEAD", "--author", "alice", "--auto-merge")
                code_v, text_v = self.bee("validate")
                own_ones = bee.check_pr(bee.Registry(self.dir), base, "HEAD", "alice", github_id=number_from("alice"))[0]  # without bee valider's checks
                self.assertNotIn("Traceback", text + text_v)
                if address in self.OTHER_PRS:
                    self.assertEqual((code, code_v, own_ones), (0, 0, []), text + text_v)
                    self.assertIn("FUSION_AUTO=oui", text)
                elif address in self.SAME_PR:
                    self.assertEqual((code, code_v), (1, 1), text + text_v)
                    self.assertEqual(len([p for p in own_ones if "is already linked to miniz-0099-c1" in p]), 1, own_ones)
                    self.assertIn("is already linked to miniz-0099-c1", text_v)
                    self.assertEqual(f"miniz-9001-c1.yaml: {written_one}" in text_v, address != self.SAME_PR[0], text_v)
                    self.assertEqual(f"miniz-0099-c1.yaml: {written_one}" in text_v, base == "c1-autre", text_v)
                else:
                    self.assertEqual((code, code_v), (1, 1), text + text_v)
                    self.assertTrue(any("invalid PR address" in p for p in own_ones), own_ones)
                    self.assertIn("miniz-9001-c1.yaml: pr: wrong format", text_v)

    def test_check_pr_quotes_a_declared_pr_and_task_on_one_line(self):
        """ruche-0088: the PR address and the task a contribution declares are quoted in check-pr's messages, neutralised."""
        self.reserve_on_main("miniz-0099")
        for task, address in (("miniz-0099", "pas-une-adresse"), ("miniz-0099" + FORGED_LINE, "x" + FORGED_LINE)):
            with self.subTest(task=task, address=address):
                git(self.dir, "switch", "-qfC", "citee", "main")
                git(self.dir, "clean", "-fdq")
                self.submit_with_pr("miniz-0099", address)
                path = self.dir / "contributions/miniz/miniz-0099-c1.yaml"
                bee.write_yaml(path, {**bee.read_yaml(path), "task": task})
                self.commit()
                problems_found = bee.check_pr(bee.Registry(self.dir), "main", "HEAD", "alice", github_id=number_from("alice"),
                                            pr_authors={})[0]
                self.assertIn(f"invalid PR address: {bee.cite(address)} (expected", "\n".join(problems_found))
                self.assertEqual(f"the next contribution of {bee.cite(task)} is" in "\n".join(problems_found), task != "miniz-0099")
                for p in problems_found:
                    self.assertEqual((p.count("\n"), bee.frame_markers(p)), (0, []), p)

