    # --- I3 : le conseil intègre lui-même une course de la ruche ---

    def submit_hive(self, who_is, number_of):
        code, text = self.bee("submit", "ruche-0001", "--user", who_is, "--pr", f"https://github.com/Bee-ruche/registre/pull/{number_of}")
        self.assertEqual(code, 0, text)
        return text.split("contribution ", 1)[1].split(" ", 1)[0]

    def test_I3_the_council_integrates_a_hive_race(self):
        # ruche-0001 (jeu figé) est intégrée : on repart d'une tâche ouverte, sans contribution.
        task_path = self.dir / "tasks/ruche/ruche-0001.yaml"
        task = bee.read_yaml(task_path)
        for key in ("reservation", "contribution", "parallel"):
            task.pop(key, None)
        task["status"] = "open"
        bee.write_yaml(task_path, task)
        for former in (self.dir / "contributions/ruche").glob("ruche-0001-c*.yaml"):
            former.unlink()
        self.init_git()
        self.assertEqual(self.bee("take", "ruche-0001", "--user", "alice")[0], 0)
        self.a("2026-10-27T13:00:00Z")
        self.parallel_one("ruche-0001", "bruno")
        self.parallel_one("ruche-0001", "chloe")
        self.a("2026-10-27T14:00:00Z")
        c1 = self.submit_hive("bruno", 1)
        c3 = self.submit_hive("chloe", 3)
        c2 = self.submit_hive("alice", 2)
        self.commit("course sur ruche-0001")
        self.branch("integration-manuelle")

        def write(cid, **fields):
            path = self.dir / f"contributions/ruche/{cid}.yaml"
            rec = bee.read_yaml(path)
            rec.update({"decided_at": "2026-11-05T14:00:00Z", "decision_reason": "Relue par le conseil.", **fields})
            bee.write_yaml(path, rec)

        write(c2, status="integrated")
        write(c1, status="set_aside", kept=c2)
        bee.modify_task(self.dir / "tasks/ruche/ruche-0001.yaml", status="integrated", contribution=c2)
        self.commit("c3 oubliée")
        code, text = self.verify("bidji29")
        self.assertEqual(code, 1, text)
        self.assertIn("sets aside all the rivals in the race in its favour", text)
        write(c3, status="set_aside", kept=c2)
        self.commit("toutes écartées")
        code, text = self.verify("bidji29")
        self.assertEqual(code, 0, text)
        self.assertEqual(self.verify("bidji29", "--auto-merge")[0], 3, "une décision du conseil n'est jamais fusionnée seule")
        code, text = self.verify("alice")
        self.assertEqual(code, 1, "un membre n'écarte pas")

