    def test_I6_a_duplicate_key_is_refused(self):
        self.init_git()
        self.assertEqual(self.bee("take", "miniz-0099", "--user", "alice")[0], 0)
        self.commit("réservation d'alice")
        self.a("2026-10-27T13:00:00Z")
        self.branch("duplicate")
        path = self.dir / "tasks/miniz/miniz-0099.yaml"
        text = path.read_text(encoding="utf-8")
        path.write_text(text.replace("status: reserved", "status: reserved\nparallel: []", 1).rstrip("\n")
                          + '\nparallel:\n  - user: "chloe"\n    since: "2026-10-27T13:00:00Z"\n', encoding="utf-8")
        self.commit()
        code, text = self.bee("validate")
        self.assertEqual(code, 1, text)
