        path.write_text(text.rstrip("\n") + '\nreservation:\n  user: "alice"\n  since: "2026-10-27T12:00:00Z"\n', encoding="utf-8")
        self.commit()
        code, text = self.verify("alice", "--auto-merge")
        self.assertEqual(code, 1, text)
        self.assertIn("duplicate key « reservation »", text)

