    def test_N5_a_non_finite_gain_is_refused(self):
        c1 = self.submit_0099("alice")
        for gain in ("NaN", "Infinity", "-Infinity"):
            v = self.dir / "verdict_non_fini.json"
            v.write_text('{"ci": "verte", "gain": %s, "beyond_noise": true, "changed_lines": 10}' % gain, encoding="utf-8")
            code, text = self.bee("record-verdict", c1, "--verdict", str(v), "--sha", "abc1234", "--files", self.pr_files())
            self.assertEqual(code, 1, text)
            self.assertIn("non-finite", text)
        self.assertNotIn("verdict", self.rec(c1))
        reg = bee.Registry(self.dir)
        base = {"task": "miniz-0099", "verdict": {"ci": "green", "gain": 0.05, "changed_lines": 10, "checked_files": True}}
        self.assertIsNotNone(bee.measured_gain(reg, base))
        self.assertIsNone(bee.measured_gain(reg, {**base, "verdict": {**base["verdict"], "gain": float("nan")}}))
        self.assertIsNone(bee.measured_gain(reg, {**base, "verdict": {**base["verdict"], "checked_files": False}}))
        self.assertIsNone(bee.measured_gain(reg, {**base, "verdict": {**base["verdict"], "modified_judges": [".github/x.yml"]}}))

