        bee.write_yaml(path, {**bee.read_yaml(path), "awaiting_verdict": {"reason": bee.VERDICT_WAIT["pr_closed"], "sha": "abc1234"}})
        self.assertIn("awaiting_verdict/reason is not a bee code", self.bee("validate")[1])
