    def raw_synthesis(self, who_is, next_rapporteur):
        d = self.debate()
        d.update({"synthesis": f"Synthèse publiée par {who_is}.", "synthesis_by": who_is, "synthesis_at": os.environ["BEE_NOW"],
                  "rapporteur": next_rapporteur})
        self.write(d)
        self.commit()

