    # --- 3. Révoquer un gardien ou quitter le conseil ne rend pas le registre invalide ---

    def test_F1_revoke_a_guardian_who_gave_an_agreement(self):
        self.up_to("council-approval")
        self.a("2026-11-03T10:00:00Z")
