class TestPersonalDataDetectorsPlainEnglish(unittest.TestCase):
    """ruche-0044: the R13 detectors accept ordinary English (« at the point where ») and still catch the addresses next to
    it. No registry: fast."""

    def test_honest_sentences_pass_every_detector(self):
        self.assertGreaterEqual(len(HONEST_SENTENCES_0044), 30)
        self.assertIn("at the point where", HONEST_SENTENCES_0044[0])
        for sentence in HONEST_SENTENCES_0044:
            with self.subTest(sentence=sentence):
                self.assertFalse(bee.email(sentence))
                self.assertIsNone(bee.POSTAL_ADDRESS.search(sentence))
                self.assertEqual(bee.phone(sentence), 0)
                self.assertIsNone(bee.personal_datum(sentence))
        for sentence in REFUSED_ON_PURPOSE_0044:
            with self.subTest(refused=sentence):
                self.assertEqual(bee.personal_datum(sentence), "an email address")

    def test_neighbouring_addresses_still_caught(self):
        for text in NEARBY_CONTACT_DETAILS_0044:
            with self.subTest(text=text):
                self.assertEqual(bee.personal_datum(text), "an email address")
        for text in ("alice at this point com for details", "mail at the point example org for details",
                      "alice arobase the point org pour toi"):
            with self.subTest(stream=text):
                self.assertIn("an email address", bee.agora_datum(text, "argument"))
                self.assertIn("an email address", bee.outgoing_text_refused(text, "message", 2000))
        for source in ("https://example.org/p/alice%20at%20this%20point%20com%20x",
                       "https://example.org/p/alice%20at%20the%20point%20where%20dot%20com"):
            with self.subTest(source=source):
                self.assertIn("an email address", bee.outgoing_address_refused(source, "source"))
                self.assertIn("an email address", bee.source_problem(None, source))

    def test_continuations_are_no_top_level_domain(self):
        """A determiner, "point", then an allowed word is let through: that word is no top-level domain of the snapshot."""
        self.assertGreater(len(TLD_PSL_2025_12_28), 1200)
        self.assertTrue({"com", "org", "in", "it", "is", "to", "now", "how", "one", "new", "app", "dev", "page", "you"}
                        <= TLD_PSL_2025_12_28)
        words = bee.CONTINUATIONS_EN.split("|")
        self.assertGreaterEqual(len(words), 10)
        self.assertNotIn("did", words, "applied for in ICANN's 2026 round")
        self.assertEqual([m for m in words if m in TLD_PSL_2025_12_28 or m in ISO_3166_WITHOUT_DOMAIN], [])
        # A determiner is the would-be domain, not the tld: being one is harmless there; pinned so a change is seen.
        self.assertEqual({m for m in bee.EN_DETERMINERS.split("|") if m in TLD_PSL_2025_12_28}, {"no"})


class TestPersonalDataDetectorsPlainEnglishFlows(BaseReviewRuche0020):
    """ruche-0044: the same English passes in an invitation's message (check-pr) and in an agora argument."""

    def test_english_in_an_invitation_and_in_the_agora(self):
        sentence = HONEST_SENTENCES_0044[0]
        self.a("2026-10-30T10:00:00Z")
        self.assertEqual(self.try_it(["en"], lambda _: self.propose_raw(
            message=MESSAGE_INVITATION + " " + sentence + "\n\n" + self.mention())), ["en"])
        self.branch()
        self.argue("alice", "for", sentence)
        self.publish("alice", "argument")


