        self.commit("sur main : un commentaire la nomme, entre deux autres")
        self.removal_in_pr()
        raw, marker = task.read_text(encoding="utf-8"), "# Demandé par [removed] le 12/10\n"
        self.assertIn("\nstatus: ", raw)
        without_it = raw.replace("# Demandé par octocat le 12/10\n", "")
        end_of_line = lambda text, c: re.sub(r"(?m)^(status: .*)$", lambda x: x[1] + " " + c, text, count=1)  # noqa: E731
        for name, fake in (("un autre déplacé en fin de ligne", end_of_line(without_it.replace("# Relu le 13/10\n", ""), "# Relu le 13/10")),
                          ("un autre déplacé en bas", without_it.replace("# Relu le 13/10\n", "") + "# Relu le 13/10\n"),
                          ("deux autres échangés", without_it.replace("# Relu le 13/10\n# Classé le 14/10\n", "# Classé le 14/10\n# Relu le 13/10\n")),
                          ("le marqué déplacé en fin de ligne", end_of_line(without_it, marker.strip())),
                          ("le marqué déplacé en bas", without_it + marker)):
            with self.subTest(name):
                self.change_then_refuse(lambda: task.write_text(fake, encoding="utf-8"), "miniz-0099.yaml: a requested removal changes")
        for name, correct in (("marqué là où il est", raw.replace("# Demandé par octocat le 12/10\n", marker)), ("ôté", without_it)):
            with self.subTest(name):
                task.write_text(correct, encoding="utf-8")
