class TestAgentAccountsWorkflows(BaseParallel):
    """ruche-0089: auto-integration takes a PR opened by the contribution's author's declared agent account as the author's,
    and nothing else (bee acts-for, fail closed); check-fork reads the manifest of the person."""

    step = TestAdversarialReview.step
    calls_of = staticmethod(TestAdversarialReview.calls_of)

    def test_integration_takes_the_pr_of_the_authors_agent_account_and_nothing_else(self):
        declare_agents(self.dir, (AGENT, "bidji29"), ("alice-agent", "alice"))
        self.close_gate()
        c1 = self.submit_0099("alice")
        self.verdict(c1, 0.05)
        self.review(c1, "bruno", "bidji29")
        self.a("2026-10-28T13:00:00Z")
        self.assertEqual(self.acceptance(c1)[0], 0)
        for login in (AGENT, "Alice-Agent2", "mallory", "alice-agent-x"):
            with self.subTest(pr_by=login):
                states = {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": login}}
                output_text, state, calls = self.step("Integrate what satisfies R3, close what is abandoned", states)
                self.assertIn(f"ouverte par {login}, pas par alice ; ni fusionnée ni consignée", output_text)
                self.assertFalse(self.calls_of(calls, "pr", "merge"))
                self.assertEqual(self.rec(c1)["status"], "in_review")
        # An unreadable declaration maps no one: the agent account's PR is then not the author's (fail closed).
        declaration = (self.dir / bee.AGENT_ACCOUNTS).read_text(encoding="utf-8")
        (self.dir / bee.AGENT_ACCOUNTS).write_text("accounts: [\n", encoding="utf-8")
        output_text, _, calls = self.step("Integrate what satisfies R3, close what is abandoned", {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": "alice-agent"}})
        self.assertIn("ouverte par alice-agent, pas par alice ; ni fusionnée ni consignée", output_text)
        self.assertFalse(self.calls_of(calls, "pr", "merge"))
        (self.dir / bee.AGENT_ACCOUNTS).write_text(declaration, encoding="utf-8")
        _, state, calls = self.step("Integrate what satisfies R3, close what is abandoned", {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": "alice-agent"}})
        self.assertEqual([a["args"][2] for a in self.calls_of(calls, "pr", "merge")], [PR_MINIZ + "99007"])
        self.assertEqual(self.rec(c1)["status"], "integrated")
        self.valid_one()

    def test_verdicts_take_the_pr_of_the_authors_agent_account_and_nothing_else(self):
        declare_agents(self.dir, (AGENT, "bidji29"), ("alice-agent", "alice"))
        c1 = self.submit_0099("alice")
        verdict = {"ci": "green", "gain": 0.05, "beyond_noise": True, "changed_lines": 10, "instructions": INSTRUCTIONS_N6}
        for login in (AGENT, "Alice-Agent2", "mallory", "alice-agent-x"):
            with self.subTest(pr_by=login):
                states = {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": login, "verdict": verdict}}
                output_text, _, calls = self.step("Fetch the verdicts", states, stream="verdicts.yml")
                self.assertIn(f"la PR {PR_MINIZ}99007 a été ouverte par {login}, pas par alice ; aucun verdict", output_text)
                self.assertNotIn("verdict", self.rec(c1))
                self.assertFalse(self.calls_of(calls, "run"))
        # An unreadable declaration maps no one (fail closed).
        declaration = (self.dir / bee.AGENT_ACCOUNTS).read_text(encoding="utf-8")
        (self.dir / bee.AGENT_ACCOUNTS).write_text("accounts: [\n", encoding="utf-8")
        states = {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": "alice-agent", "verdict": verdict}}
        output_text, _, _ = self.step("Fetch the verdicts", states, stream="verdicts.yml")
        self.assertIn("ouverte par alice-agent, pas par alice ; aucun verdict", output_text)
        self.assertNotIn("verdict", self.rec(c1))
        (self.dir / bee.AGENT_ACCOUNTS).write_text(declaration, encoding="utf-8")
        self.step("Fetch the verdicts", states, stream="verdicts.yml")
        self.assertEqual((self.rec(c1)["verdict"]["ci"], self.rec(c1)["verdict"]["sha"]), ("green", "abc1234"))
        self.valid_one()

    def test_closing_the_pr_of_a_set_aside_contribution(self):
        declare_agents(self.dir, (AGENT, "bidji29"), ("chloe-agent", "chloe"))
        self.close_gate()
        c1 = self.submit_0099("alice")
        self.a("2026-10-27T13:00:00Z")
        self.parallel_one("miniz-0099", "chloe")
        c2 = self.submit("miniz-0099", "chloe", 4242)
        self.verdict(c1, 0.05)
        self.review(c1, "bruno", "bidji29")
        self.a("2026-10-31T12:00:00Z")
        self.step("Integrate what satisfies R3, close what is abandoned", {PR_MINIZ + "99007": {"state": "OPEN", "head": "abc1234", "author": "alice"},
                                PR_MINIZ + "4242": {"state": "OPEN", "head": "beefcafe", "author": AGENT}})
        self.assertEqual((self.rec(c1)["status"], self.rec(c2)["status"]), ("integrated", "set_aside"))
        output_text, state, calls = self.step("Close the PRs of the contributions set aside")
        self.assertIn(f"ouverte par {AGENT}, pas par chloe ; on ne la ferme pas", output_text)
        self.assertFalse(self.calls_of(calls, "pr", "close"))
        state[PR_MINIZ + "4242"]["author"] = "chloe-agent"
        (self.dir.parent / "pr_state.json").write_text(json.dumps(state), encoding="utf-8")
        _, _, calls = self.step("Close the PRs of the contributions set aside")
        self.assertEqual([a["args"][2] for a in self.calls_of(calls, "pr", "close")], [PR_MINIZ + "4242"])

    def test_check_fork_reads_the_manifest_of_the_person(self):
        fork = pathlib.Path(self.temp.name) / "fork"
        fork.mkdir()
        (fork / "miniz_tdef.c").write_text("".join(f"ligne {i}\n" for i in range(100)), encoding="utf-8")
        git(fork, "init", "-q", "-b", "master")
        git(fork, "-c", "user.name=t", "-c", "user.email=t@t", "add", "-A")
        git(fork, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "base")
        git(fork, "switch", "-qc", "task/miniz-0099")
        (fork / "miniz_tdef.c").write_text("".join(f"ligne {i}\n" for i in range(99)) + "ligne cent\n", encoding="utf-8")
        (fork / "CONTRIBUTION.yaml").write_text(FILLED_MANIFEST.replace("user: alice", "user: bidji29"), encoding="utf-8")
        git(fork, "-c", "user.name=t", "-c", "user.email=t@t", "add", "-A")
        git(fork, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "workdir")
        for author, expected in ((AGENT, 0), ("bidji29", 0), ("alice", 1), ("LaRuche-Architect", 1)):
            with self.subTest(author=author):
                code, text = self.bee("check-fork", "--task", "miniz-0099", "--base", "master", "--repo", str(fork), "--author", author)
                self.assertEqual(code, expected, text)
        self.assertIn("user « bidji29 » differs from the PR's author « LaRuche-Architect »", text)


# --- ruche-0094: a registry contribution merged into main is recorded by the integration workflow ---

REGISTRY_PR = "https://github.com/Bee-ruche/registre/pull/"
MERGED_HEAD = "c0ffee" + "0" * 34
SUMMARY_9094 = "Merged registry contributions are recorded by the integration workflow | from GitHub's facts."
AGENT_WHO = f"{AGENT} (declared agent account of bidji29, a council member), by merging"
VALIDATION_YML, COMMON_JUDGE_YML = ".github/workflows/validation.yml", ".github/workflows/juge-commun.yml"


def head_run(**fields):
    """A run of validation.yml for PR #9201 on its merged head, as GitHub's REST API gives it (actions/runs): green unless `champs`
    say otherwise."""
    return {"id": 1, "path": VALIDATION_YML, "event": "pull_request", "head_sha": MERGED_HEAD, "head_branch": "task/9201",
            "head_repository": {"full_name": "Bee-ruche/registre"}, "status": "completed", "conclusion": "success", **fields}


class TestRegistryMergeRecorded(BaseParallel):
    """ruche-0094: when the PR a registry contribution declares is merged into main by a council member's account or a council
    member's declared agent account, auto-integration records it as the council does by hand, from GitHub's REST answers and
    main's history only: the contribution and its task « integrated » with the merge time, merge commit and merged head, the account
    as GitHub reports it, and a row in docs/decisions.md. Anything else: no record, a notice. Fork contributions are unchanged
    (their own tests)."""

    step = TestAdversarialReview.step
    calls_of = staticmethod(TestAdversarialReview.calls_of)
    commit = TestAdversarialReview.commit

    def setUp(self):
        super().setUp()
        declare_agents(self.dir, (AGENT, "bidji29"))
        (self.dir / "tasks/ruche/ruche-9094.yaml").write_text(
            OPTIMIZATION_TASK.replace("miniz-0099", "ruche-9094").replace("project: miniz", "project: ruche")
            .replace("category: lossless-compression", "category: ruche").replace("type: optimization", "type: test")
            .replace("metric: debit_compression_n6", "metric: null").replace("compressed_output: identical\n", "")
            .replace("status: open", "node: projects/ruche/ruche\nstatus: open").replace("created_by: tests", "created_by: council"),
            encoding="utf-8")
        self.cid, self.pr = "ruche-9094-c1", REGISTRY_PR + "9201"
        self.assertEqual(self.bee("take", "ruche-9094", "--user", "bidji29")[0], 0)
        git(self.dir, "init", "-q", "-b", "main")
        self.commit("main: the task reserved")
        self.base_pr = git(self.dir, "rev-parse", "HEAD").strip()  # GitHub's base.sha of PR #9201: a commit of main before it
        self.change("README.md", "an earlier change")
        self.commit("main: an earlier merge")
        self.earlier = git(self.dir, "rev-parse", "HEAD").strip()

    def change(self, relative_one, text):
        path = self.dir / relative_one
        path.write_text(path.read_text(encoding="utf-8") + f"\n{text}\n", encoding="utf-8")

    def submitted_one(self, in_the_pr=True, travail=True, also=None):
        """bidji29 submits ruche-9094-c1 inside the code PR it declares: the contribution reaches main with the PR's (squash) merge
        commit, returned, which also changes README.md (travail) and what `aussi` writes. dans_la_pr=False: submitted by a commit of
        its own, before the PR's merge commit (also returned)."""
        self.a("2026-10-27T13:00:00Z")
        code, text = self.bee("submit", "ruche-9094", "--user", "bidji29", "--pr", self.pr, "--summary", SUMMARY_9094)
        self.assertEqual(code, 0, text)
        if not in_the_pr:
            self.commit("a separate submission")
        if travail:
            self.change("README.md", "PR #9201's change")
        if also:
            also()
        self.commit("PR #9201, squash-merged")
        return git(self.dir, "rev-parse", "HEAD").strip()

    def states(self, merge_sha, **pr):
        """The stub's state of PR #9201: merged into main by the agent principal's account, which opened it, at its merge commit
        (merge_sha: not fusion, whose English name is the key "merge" a test passes in pr, ruche-0153)."""
        return {self.pr: {"state": "MERGED", "head": MERGED_HEAD, "merge": merge_sha, "author": AGENT, "base": "main", "fusionnee_par": AGENT,
                          "merged_at": "2026-10-27T14:00:00Z", "changed_files": self.files_of(merge_sha), "base_sha": self.parent_of(merge_sha), **pr}}

    def parent_of(self, merge):
        """GitHub's base.sha of a squash or a merge commit's PR: its first parent (the start of the history if it has none)."""
        r = subprocess.run(["git", "-C", str(self.dir), "rev-parse", f"{merge}^1"], capture_output=True, text=True)
        return r.stdout.strip() if r.returncode == 0 else self.base_pr

    def files_of(self, merge):
        """The files a commit of main changes: GitHub's changed_files of the PR it squashes or merges (0 if it is not on main)."""
        r = subprocess.run(["git", "-C", str(self.dir), "diff", "--name-only", f"{merge}^1", merge], capture_output=True, text=True)
        return len(r.stdout.splitlines()) if r.returncode == 0 else 0

    def answers(self, merge, runs=None, **fields):
        """GitHub's answers as auto-integration stores them for bee record-merge (pulls/N, actions/runs), `champs` changed."""
        api = pathlib.Path(self.temp.name) / "api"
        api.mkdir(exist_ok=True)
        pr = {"number": 9201, "state": "closed", "merged": True, "merged_at": "2026-10-27T14:00:00Z", "merge_commit_sha": merge,
              "head": {"sha": MERGED_HEAD, "ref": "task/9201", "repo": {"full_name": "Bee-ruche/registre"}}, "base": {"ref": "main", "sha": self.parent_of(merge)},
              "user": {"login": AGENT}, "merged_by": {"login": AGENT}, "changed_files": self.files_of(merge), **fields}
        (api / "pr.json").write_text(json.dumps(pr), encoding="utf-8")
        runs = [head_run()] if runs is None else runs
        (api / "runs.json").write_text(json.dumps({"workflow_runs": runs}), encoding="utf-8")
        return str(api)

    def files(self):
        """What a record writes: the contribution, its task, docs/decisions.md."""
        return [(self.dir / c).read_text(encoding="utf-8") for c in
                (f"contributions/ruche/{self.cid}.yaml", "tasks/ruche/ruche-9094.yaml", bee.DECISIONS)]

    def first_line(self):
        """The first row of docs/decisions.md's table (the most recent first)."""
        lines = (self.dir / bee.DECISIONS).read_text(encoding="utf-8").splitlines()
        return lines[lines.index(bee.DECISIONS_HEADER.strip()) + 1]

    def lines_of(self, cid):
        """The rows of docs/decisions.md that record `cid` (its id in the second cell)."""
        return [l for l in (self.dir / bee.DECISIONS).read_text(encoding="utf-8").splitlines()
                if re.match(rf"\| [^|]+ \| {re.escape(cid)} integrated \(", l)]

    def test_a_merged_registry_pr_is_recorded_from_github_s_facts(self):
        merge = self.submitted_one()
        output_text, _, calls = self.step("Integrate what satisfies R3, close what is abandoned", self.states(merge))
        rec = self.rec(self.cid)
        self.assertEqual((rec["status"], rec["decided_at"], rec["merge_sha"]), ("integrated", "2026-10-27T14:00:00Z", merge), output_text)
        self.assertEqual(rec["decision_reason"], f"Hive tooling contribution: registry PR #9201 merged at commit c0ffee0 by {AGENT}, "
                                                "declared agent account of bidji29, CI green on the merged commit.")
        self.assertEqual(self.task("ruche-9094")["status"], "integrated")
        self.assertEqual(self.first_line(), (
            "| 2026-10-27 | ruche-9094-c1 integrated (PR #9201, merged at the judged commit c0ffee0): Merged registry contributions are "
            "recorded by the integration workflow \\| from GitHub's facts | Task ruche-9094; recorded by the integration workflow from "
            f"GitHub's facts: merged at 2026-10-27T14:00:00Z, merge commit {merge[:7]}, CI green on the merged commit (ruche-0094) | "
            f"{AGENT_WHO} |"))
        self.assertIn(f"✓ {self.cid} recorded as integrated", output_text)
        # GitHub's REST answers only: the PR (its title and body say otherwise, unread) and the runs of its merged head; never its
        # files nor their content, and the robot never merges a registry PR.
        self.assertEqual(sorted({a["args"][1].split("?")[0] for a in self.calls_of(calls, "api")} - {"graphql"}),  # ruche-0122: bulk read
                         ["repos/Bee-ruche/registre/actions/runs", "repos/Bee-ruche/registre/pulls/9201"])
        self.assertIn(f"repos/Bee-ruche/registre/actions/runs?head_sha={MERGED_HEAD}&event=pull_request&per_page=100",
                      [a["args"][1] for a in calls])
        self.assertFalse(self.calls_of(calls, "pr", "merge"))
        self.valid_one()

    def test_the_record_has_the_form_of_a_hand_made_one(self):
        merge = self.submitted_one()
        task_before = (self.dir / "tasks/ruche/ruche-9094.yaml").read_text(encoding="utf-8")
        self.step("Integrate what satisfies R3, close what is abandoned", self.states(merge))
        self.valid_one()
        # Field by field against a record the council made by hand (frozen fixture): the same fields in the same order, of the
        # same types and forms.
        by_hand, robot = bee.read_yaml(self.dir / "contributions/ruche/ruche-0014-c1.yaml"), self.rec(self.cid)
        self.assertEqual(list(robot), list(by_hand))
        for key, value in by_hand.items():
            with self.subTest(key=key):
                self.assertIs(type(robot[key]), type(value))
        self.assertEqual((robot["status"], robot["reviews"]), (by_hand["status"], by_hand["reviews"]))
        for key, form_text in (("submitted_at", r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ"), ("engaged_since", r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ"),
                           ("decided_at", r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ"), ("merge_sha", r"[0-9a-f]{40}"),
                           ("pr", r"https://github\.com/Bee-ruche/registre/pull/\d+")):
            for rec in (by_hand, robot):
                self.assertRegex(rec[key], f"^{form_text}$")
        # The task: only its status changes, as in the council's records (taches/ruche/ruche-0014.yaml: integree, its contribution).
        self.assertEqual((self.dir / "tasks/ruche/ruche-9094.yaml").read_text(encoding="utf-8"),
                         task_before.replace("\nstatus: in_review\n", "\nstatus: integrated\n"))
        main_task = bee.read_yaml(self.dir / "tasks/ruche/ruche-0014.yaml")
        self.assertEqual((main_task["status"], main_task["contribution"]), ("integrated", "ruche-0014-c1"))
        self.assertEqual((self.task("ruche-9094")["status"], self.task("ruche-9094")["contribution"]), ("integrated", self.cid))
        # The row: the form of the council's rows (that of ruche-0043-c1, recorded by hand on 1 Nov).
        form_text = r"^\| \d{4}-\d\d-\d\d \| ruche-\d{4}-c\d+ integrated \(PR #\d+, merged at the judged commit [0-9a-f]{7}\): [^|]+ \| .+ \| [^|]+ \|$"
        self.assertRegex(self.lines_of("ruche-0043-c1")[0], form_text)
        self.assertRegex(self.first_line().replace("\\|", "/"), form_text)

    def test_the_who_column_names_the_merging_account_as_github_reports_it(self):
        """Who acted through an account, the robot cannot know (the agent principal has merged under the founder's account): it
        names the account and what main said it was before the merge, nothing more."""
        merge = self.submitted_one()
        for by, account, who_is in ((AGENT, "declared agent account of bidji29", AGENT_WHO),
                                 ("bidji29", "the account of a council member", "bidji29 (account of a council member), by merging")):
            with self.subTest(by=by):
                code, text = self.bee("record-merge", self.cid, "--api", self.answers(merge, merged_by={"login": by}))
