    def test_the_brake_counts_persons_without_the_abstentions(self):
        self.a("2026-10-30T10:00:00Z")
        self.linked()
        self.a("2026-10-30T12:00:00Z")
        self.active("bruno", "alice", "farid")  # bruno submits miniz-0099-c1; alice and farid, one person, measure it
        self.assertEqual(bee.active_members(bee.Registry(self.dir)), {"bruno", "alice"})
        # An abstention and an argument take no position: chloe is not active.
        self.ok("review", "miniz-0099-c1", "--user", "chloe", "--opinion", "abstention", "--reason", "Conflit d'intérêts : je n'en juge pas.")
        self.ok("debate", "argue", "D-0001", "--user", "chloe", "--position", "for", "--text", "Un garant public engage sa réputation.")
        self.commit("abstention et argument")
        self.assertEqual(bee.active_members(bee.Registry(self.dir)), {"bruno", "alice"})
        self.ok("review", "miniz-0099-c1", "--user", "gaspard", "--opinion", "unfavorable", "--reason", "Le banc ne montre aucun gain.")
        self.commit("relecture de gaspard")
        reg = bee.Registry(self.dir)
        self.assertEqual(bee.active_members(reg), {"bruno", "alice", "gaspard"})
        self.assertEqual(bee.brake_state(reg)["active_members"], 3)
        # The cap still weighs the abstention as coordination work.
        self.assertEqual(sum(1 for g in bee.recent_gestures(reg)[0] if g[3] == "reviews"), 2)

    def test_a_guardian_and_its_linked_accounts(self):
        self.a("2026-10-30T09:00:00Z")
        for who_is in ("gina", "gina2"):
            self.ok("register", "--login", who_is, "--account-created-on", "2020-01-01")
        self.commit("gina et gina2 s'inscrivent")
        self.linked("gina", "gina2")
        # A status never follows a link: gina2 is not a guardian because gina is.
        reg = bee.Registry(self.dir)
        self.assertTrue(reg.identities.same_one("gina", "gina2"))
        self.assertFalse("gina2" in reg.guardians or "gina2" in reg.privileged_ones() or "gina2" in bee.guardians_in_office(reg))
        self.a("2026-10-30T10:00:00Z")
        self.branch()
        self.invite("gina2")
        self.publish("gina2", "invitation", free_one=False)
        self.a("2026-11-02T11:00:00Z")
        self.ko("gina2 is not a guardian in office", "invitation", "guardian-approval", "I-0001", "--user", "gina2")
        # Neither does gina give her accord to what her linked account proposed.
        self.ko("no one approves their own invitation (nor that of a linked account)", "invitation", "guardian-approval", "I-0001",
                "--user", "gina")
        self.branch("approval")
        inv = self.invitation()
        self.write_invitation({**inv, "guardian_approval": {"by": "gina", "at": os.environ["BEE_NOW"]}})
        self.commit()
        self.refused("gina", "nor that of a linked account")
        self.abandon("approval")
        # Two guardians who are one person: one guardian for R13's brake, and a warning, never a refusal.
        (self.dir / "governance/guardians.yaml").write_text(
            "members:\n  - login: gina\n    guarantor: hector\n  - login: gina2\n    guarantor: hector\n", encoding="utf-8")
        reg = bee.Registry(self.dir)
        self.assertEqual((bee.brake_state(reg)["guardians_in_office"], len(bee.guardians_in_office(reg))), (1, 2))
        self.assertIn("⚠ guardians gina and gina2: the same person (linked accounts)", self.ok("validate"))
        # One reviewer: gina reviews bruno's contribution at the judged commit; gina2 is the same reviewer, on the same commit.
        self.commit("deux gardiens")
        self.take_and_merge("bruno")
        cid = self.submit_and_merge("bruno", "miniz-0099", 77005)
        self.verdict(cid)
        self.ok("review", cid, "--commit", "abc1234", "--user", "gina", "--opinion", "favorable", "--reason", "Relu en entier, banc rejoué.")
        self.ko("gina2 has already reviewed", "review", cid, "--commit", "abc1234", "--user", "gina2", "--opinion", "favorable",
                "--reason", "Relu en entier, banc rejoué.")
        rec = bee.read_yaml(self.dir / f"contributions/miniz/{cid}.yaml")
        rec["reviews"].append({**rec["reviews"][0], "reviewer": "gina2"})
        reg = bee.Registry(self.dir)
        self.assertEqual([r["reviewer"] for r in bee.last_reviews(rec, reg.identities).values()], ["gina2"])
        self.assertIn("gina2 already reviewed commit abc1234", bee.refused_review(rec["reviews"][:1], rec["reviews"][1], reg.identities))

    def test_a_status_never_follows_a_link(self):
        """The council may link by hand (ruche-0118): bidji29 with chloe, the guarantor hector with gaspard. Neither chloe nor
        gaspard gains the status: council, guarantor, R8's bootstrap cap."""
        for who_is in ("bidji29", "hector"):
            self.ok("register", "--login", who_is, "--account-created-on", "2020-01-01")
        for principal, other in (("bidji29", "chloe"), ("hector", "gaspard")):
            self.by_hand(principal, other_accounts=[number_from(other)])
            self.by_hand(other, account_of=number_from(principal))
        (self.dir / "governance/guardians.yaml").write_text(
            "members:\n  - login: gina\n    guarantor: hector\n  - login: ivan\n    guarantor: gaspard\n", encoding="utf-8")
        self.ok("validate")
        reg = bee.Registry(self.dir)
        self.assertTrue(reg.identities.same_one("bidji29", "chloe") and reg.identities.same_one("hector", "gaspard"))
        self.assertEqual([q in s for q, s in (("chloe", reg.council), ("chloe", reg.privileged_ones()), ("gaspard", reg.guarantors))], [False] * 3)
        self.assertEqual(bee.guardians_in_office(reg), {"gina"})  # ivan's guarantor would be gaspard: not a guarantor
        before = bee.read_instant("2026-11-02T12:00:00Z", "test")
        self.assertEqual((bee.r8_maximum(reg, "bidji29", [], before), bee.r8_maximum(reg, "chloe", [], before)), (8, 3))

