    def test_the_levels_are_never_pooled(self):
        """alice has ten contributions integrated and no review point (Contributeur), farid ten review points and no contribution
        (Nouveau): pooled, they would make one Confirmé (weight 2). Linked, each keeps its own level, and their one voice weighs as
        the best of them alone (1)."""
        self.a("2026-10-30T10:00:00Z")
        self.linked()
        for _ in range(10):
            self.contributors("alice")
        for n in range(10):
            tid = f"miniz-92{n:02d}"
            (self.dir / f"tasks/miniz/{tid}.yaml").write_text(
                OPTIMIZATION_TASK.replace("miniz-0099", tid).replace("status: open", f"status: integrated\ncontribution: {tid}-c1"),
                encoding="utf-8")
            bee.write_yaml(self.dir / f"contributions/miniz/{tid}-c1.yaml", {
                "id": f"{tid}-c1", "task": tid, "author": "bruno", "pr": f"https://github.com/Bee-ruche/minizBee/pull/92{n:02d}",
                "status": "integrated", "submitted_at": "2026-10-20T12:00:00Z", "verdict": {"sha": "abc1234"},
                "reviews": [{"reviewer": "farid", "opinion": "favorable", "reason": "Relu en entier.", "at": "2026-10-21T12:00:00Z", "sha": "abc1234"}]})
        rec = {"id": "miniz-9006-c1", "task": "miniz-9006", "author": "chloe"}
        bee.write_yaml(self.dir / "votes/miniz-9006-c1/farid.yaml", {"voter": "farid", "subject": "miniz-9006-c1", "value": 1,
                                                                          "at": os.environ["BEE_NOW"]})
        before = bee.Registry(self.dir)
        before.adopt(before.identities.by_account())  # who is who without the link
        levels_before = bee.compute_levels(before)
        best_one = max(bee.voice_weight(before, levels_before, q) for q in ("alice", "farid"))
        reg = bee.Registry(self.dir)
        levels = bee.compute_levels(reg)
        self.assertEqual([(levels[q]["integrated"], levels[q]["reviews"], bee.level_of(levels, q)) for q in ("alice", "farid")],
                         [(10, 0, "Contributor"), (0, 10, "New")])
        self.assertEqual((best_one, [bee.voice_weight(reg, levels, q) for q in ("alice", "farid")]), (1, [1, 1]))
        self.assertEqual((bee.net_vote(before, rec, levels_before), bee.net_vote(reg, rec, levels)), (0, 1))
        self.assertLessEqual(bee.net_vote(reg, rec, levels), best_one)

    def test_a_link_never_makes_main_invalid(self):
        """History as written stays valid; from the link on, it counts by person: farid's earlier review of and vote for alice's
        contribution stop counting, give no review point, and the four engagements they hold allow no fifth."""
        self.a("2026-10-30T10:00:00Z")
        self.contributors("farid")
        self.commit("farid est Contributeur")
        self.take_and_merge("alice")
        cid = self.submit_and_merge("alice", "miniz-0099", 77003)
        self.verdict(cid)
        for name, command in (("review", ["review", cid, "--commit", "abc1234", "--user", "farid", "--opinion", "favorable",
                                            "--reason", "Relu en entier, banc rejoué."]),
                              ("vote", ["vote", cid, "--user", "farid", "--value", "1"])):
            self.branch(name)
            self.ok(*command)
            self.publish("farid", name, name=name)
        for who_is, task in (("farid", "miniz-9001"), ("farid", "miniz-9003"), ("alice", "miniz-9004"), ("alice", "miniz-9005")):
            self.take_and_merge(who_is, task)
        reg = bee.Registry(self.dir)
        rec = reg.record(cid)[1]
        self.assertEqual(([r["reviewer"] for r in bee.reviews_survey(reg, rec, bee.compute_levels(reg))["favorable_ones"]],
                          bee.net_vote(reg, rec, bee.compute_levels(reg))), (["farid"], 1))
        self.linked()  # the confirming PR passes the gate and bee valider, on the history as written
        self.ok("validate")
        reg = bee.Registry(self.dir)
        rec = reg.record(cid)[1]
        self.assertEqual((bee.reviews_survey(reg, rec, bee.compute_levels(reg))["favorable_ones"], bee.net_vote(reg, rec, bee.compute_levels(reg))), ([], 0))
        bee.write_yaml(self.dir / f"contributions/miniz/{cid}.yaml", {**rec, "status": "integrated"})
        self.assertEqual(bee.compute_levels(bee.Registry(self.dir))["farid"]["reviews"], 0)
        self.ko("rule R8: alice already has 4", "take", "miniz-9006", "--user", "alice")

    def test_the_agreement_of_a_guardian_is_judged_by_person_whatever_the_order_of_the_guardians(self):
        """Every guardian entry of a person counts, in any order of governance/guardians.yaml, and guarantors compare as persons:
        gina and gina2 are one person, under hector through gina; neither gives an accord on hector's invitation. gina's
        guarantor hector and jules's hector2 are one person: gina gives no accord on jules's. chloe, under ivan, is not refused."""
        self.a("2026-09-30T09:00:00Z")
        for who_is in ("gina", "gina2", "hector", "hector2", "jules"):
            self.ok("register", "--login", who_is, "--account-created-on", "2020-01-01")
        self.commit("inscriptions")
        self.linked("gina", "gina2")
        self.linked("hector", "hector2")
        (self.dir / "governance/guarantors.yaml").write_text("members:\n" + "".join(
            f"  - login: {g}\n    public_identity: {g.title()}\n" for g in ("hector", "hector2", "ivan")), encoding="utf-8")
        self.a("2026-10-30T10:00:00Z")
        self.invite("hector")
        self.invite("jules", "github:exemple-deux")
        self.commit("deux invitations")
        self.a("2026-11-02T11:00:00Z")
        for guardians, invitation, who_is, refuse in (
                ((("gina", "hector"), ("gina2", "ivan"), ("chloe", "ivan")), "I-0001", "gina", True),
                ((("gina", "hector"), ("gina2", "ivan"), ("chloe", "ivan")), "I-0001", "gina2", True),
                ((("gina2", "ivan"), ("gina", "hector"), ("chloe", "ivan")), "I-0001", "gina", True),
                ((("gina2", "ivan"), ("gina", "hector"), ("chloe", "ivan")), "I-0001", "gina2", True),
                ((("gina2", "ivan"), ("gina", "hector"), ("chloe", "ivan")), "I-0001", "chloe", False),
                ((("gina", "hector"), ("jules", "hector2"), ("chloe", "ivan")), "I-0002", "gina", True),
                ((("gina", "hector"), ("jules", "hector2"), ("chloe", "ivan")), "I-0002", "chloe", False)):
            with self.subTest(guardians=guardians, invitation=invitation, who_is=who_is):
                (self.dir / "governance/guardians.yaml").write_text(
                    "members:\n" + "".join(f"  - login: {p}\n    guarantor: {g}\n" for p, g in guardians), encoding="utf-8")
                self.commit("guardians")
                chunk = f"the guarantor of {who_is} is the proposer, or also directs the proposer"
                text = self.bee("invitation", "guardian-approval", invitation, "--user", who_is)[1]
                self.assertEqual(chunk in text, refuse, text)
                if refuse and who_is == "gina" and invitation == "I-0001":  # the gate, as the tool
                    self.branch("approval")
                    inv = bee.read_yaml(self.invitation_path(invitation))
                    self.write_invitation({**inv, "guardian_approval": {"by": who_is, "at": os.environ["BEE_NOW"]}}, invitation)
                    self.commit()
                    self.refused(who_is, chunk)
                    self.abandon("approval")

