        self.ko(reporter, "report", "--user", "farid", "--accounts", "bruno", "chloe", "--reason", "cross_votes")
        self.refused_by_hand("farid", "S-0003", reporter, accounts=["bruno", "chloe"])
        self.refused_by_hand("gaspard", "S-0003", reporter, author="agent-de-gaspard", accounts=["bruno", "chloe"])
        # bee.yaml's setting: raised by the council, the third passes.
