# --- ruche-0145: the switch's hand-made part (docs/english-migration.md, sections 12 and 13), one class per piece ---

class TestRetiredNamesRuche0145(BaseDressRehearsal):
    """R-q: a path the switch retired is refused by the gate to everyone (the council too), and never read as data."""

    def test_the_guard_is_the_maps_list_and_refuses_retired_paths_only(self):
        names = yaml.safe_load((ROOT / "tools/migration/names.yaml").read_text(encoding="utf-8"))
        self.assertEqual(list(bee.RETIRED_NAMES), names["retired"])
        for path in ("taches/miniz/miniz-0099.yaml", "REGLES.md", "COMMANDEMENTS.md", "outils/bee.py", "outils/migration/names.yaml",
                     "gouvernance/conseil.yaml", "invitations/ne-plus-contacter.yaml", "docs/securite.md", "arbre/SENS.md",
                     "outils/juge/juge.py"):  # ruche-0148: the common judge's old folder
            self.assertIn(f"{path}: a name retired by the switch to English", bee.retired_name(path) or "", path)
        for path in ("tasks/miniz/miniz-0099.yaml", "RULES.md", "COMMANDMENTS.md", "tools/bee.py", "tools/migration/names.yaml",
                     "tools/judge/judge.py", "invitations/do-not-contact.yaml", "docs/security.md", "taches", "Taches/x.yaml", "docs/decisions.md"):
            self.assertIsNone(bee.retired_name(path), path)
        tracked = subprocess.run(["git", "-C", str(ROOT), "ls-files", "-z"], capture_output=True, check=True).stdout.decode().split("\0")
        self.assertEqual([p for p in tracked if p and bee.retired_name(p)], [])  # the switch left none

    def test_the_gate_refuses_a_retired_path_to_everyone_and_the_english_path_passes(self):
        for who in ("bidji29", "gaspard"):
            with self.subTest(who=who):
                self.branch(f"ancien-{who}")
                (self.dir / "taches/miniz").mkdir(parents=True, exist_ok=True)
                shutil.copy(self.task_path(), self.dir / "taches/miniz/miniz-0099.yaml")
                (self.dir / "REGLES.md").write_text("x\n", encoding="utf-8")
                self.commit()
                for path in ("taches/miniz/miniz-0099.yaml", "REGLES.md"):
                    self.refused(who, f"{path}: a name retired by the switch to English (ruche-0145)")
        self.branch("honnete")
        self.ok("note", "miniz-0099", "--user", "gaspard", "--text", "Une piste.")
        self.commit()
        self.self_service("gaspard", "note")
        git(self.dir, "switch", "-q", "main")  # a stale retired file on main: deleting it is the council's, as any council file
        (self.dir / "REGLES.md").write_text("x\n", encoding="utf-8")
        self.commit("a stale file")
        self.branch("suppression")
        git(self.dir, "rm", "-q", "REGLES.md")
        self.commit()
        self.assertEqual(self.verify("bidji29")[0], 0)
        self.refused("gaspard", "REGLES.md: change reserved for the human council")


class TestRenamedCommandsRuche0145(BaseTest):
    """No aliases (plan, section 2; section 12, change 10): an old command name, where the parser reads a command, prints the new
    one (and a GitHub ::error:: line), exits 2 and runs nothing; the same word anywhere else is what it was."""

    def test_the_table_is_the_maps_and_names_real_commands(self):
        cli = yaml.safe_load((ROOT / "tools/migration/names.yaml").read_text(encoding="utf-8"))["cli"]["commands"]
        want = {f"bee {o}": n for o, n in cli.items() if " " not in o and o != n}
        want |= {f"bee {n.split()[0]} {o.split()[1]}": n.split()[1] for o, n in cli.items() if " " in o and o.split()[1] != n.split()[1]}
        self.assertEqual(bee.RENAMED_COMMANDS, want)

        def choices(parser):  # {prog: the names it reads in a command's place}
            out = {}
            for a in parser._actions:
                if not a.option_strings and a.choices is not None:
                    out.setdefault(parser.prog, set()).update(a.choices)
                    for sub in (a.choices.values() if isinstance(a.choices, dict) else ()):
                        out |= choices(sub)
            return out
        real = choices(bee.build_parser())
        for old, new in bee.RENAMED_COMMANDS.items():
            prog, word = old.rsplit(" ", 1)
            with self.subTest(old=old):
                self.assertIn(new, real[prog])  # the new name runs
                self.assertNotIn(word, real[prog])  # the old one is no command of that parser

    def test_an_old_command_is_refused_with_its_new_name_and_runs_nothing(self):
        path = self.dir / "tasks/miniz/miniz-0099.yaml"
        before = path.read_bytes()
        for argv, old, new in ((["prendre", "miniz-0099", "--utilisateur", "alice"], "bee prendre", "bee take"),
                               (["prendre", "--help"], "bee prendre", "bee take"),
                               (["debate", "argumenter", "D-0001", "--user", "alice", "--position", "pour"], "bee debate argumenter", "bee debate argue"),
                               (["invitation", "ecarter", "I-0001"], "bee invitation ecarter", "bee invitation dismiss"),
                               (["merge-pass", "preparer", "--dir", str(self.dir / "passe")], "bee merge-pass preparer", "bee merge-pass prepare")):
            with self.subTest(argv=argv):
                code, text = self.bee(*argv)
                self.assertEqual(code, 2, text)
                self.assertIn(f"::error title=bee::« {old} » was renamed « {new} » by the switch to English (ruche-0145): nothing was run", text)
                self.assertIn(f"bee: « {old} » was renamed « {new} »", text)
                self.assertNotIn("usage:", text)  # not --help: the forks' check-fork probe sees a failure, never an old command's usage
        self.assertEqual(path.read_bytes(), before, "nothing written")
        self.assertFalse((self.dir / "passe").exists())
        self.assertEqual(self.bee("take", "miniz-0099", "--user", "alice")[0], 0)  # the new name runs
        self.assertEqual(self.task("miniz-0099")["reservation"]["user"], "alice")
        # the same word elsewhere than in a command's place: a text, an option's value, a mistyped command
        code, text = self.bee("note", "miniz-0099", "--user", "alice", "--text", "prendre")
        self.assertEqual(code, 0, text)
        self.assertEqual(self.task("miniz-0099")["notes"][-1]["text"], "prendre")
        with self.assertRaises(SystemExit), contextlib.redirect_stderr(io.StringIO()) as err:
            bee.principal(["--registry", str(self.dir), "list", "--status", "prendre"])
        self.assertIn("invalid choice", err.getvalue())
        with self.assertRaises(SystemExit), contextlib.redirect_stderr(io.StringIO()) as err:
            bee.principal(["--registry", str(self.dir), "prendr"])
        self.assertIn("invalid choice", err.getvalue())

    def test_bee_registre_alone_is_refused_never_the_tools_own_registry(self):
        env = {k: v for k, v in os.environ.items() if k not in ("BEE_REGISTRY", "BEE_REGISTRE")}
        with mock.patch.dict(os.environ, {**env, "BEE_REGISTRE": str(self.dir)}, clear=True):
            out = io.StringIO()
            with contextlib.redirect_stderr(out), contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(bee.principal(["validate"]), 2)
            self.assertIn("BEE_REGISTRE was renamed BEE_REGISTRY", out.getvalue())
            self.assertEqual(self.bee("validate")[0], 0)  # --registry given: nothing falls back
        with mock.patch.dict(os.environ, {**env, "BEE_REGISTRE": "/nowhere", "BEE_REGISTRY": str(self.dir)}, clear=True):
            with contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(bee.principal(["validate"]), 0)


class TestAlreadyNamedRuche0145(unittest.TestCase):
    """already_named (who has ever been on the council or a guardian: a report decided by them stays decided by a known account)
    reads the lists under their pre-switch names and keys too (plan, section 12, change 1)."""

    def test_someone_named_only_before_the_switch_is_still_found(self):
        with tempfile.TemporaryDirectory() as folder:
            root = pathlib.Path(folder)
            git(root, "init", "-q", "-b", "main")

            def commit(files, message):
                for path, text in files.items():
                    (root / path).parent.mkdir(parents=True, exist_ok=True)
                    (root / path).write_text(text, encoding="utf-8") if text is not None else (root / path).unlink()
                git(root, "add", "-A")
                git(root, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", message)
            commit({"gouvernance/conseil.yaml": "membres:\n- pseudo: bidji29\n", "gouvernance/gardiens.yaml": "membres:\n- pseudo: Zoe\n"},
                   "before the switch")
            commit({"gouvernance/gardiens.yaml": "membres: []\n"}, "Zoe leaves, before the switch")
            commit({"gouvernance/conseil.yaml": None, "gouvernance/gardiens.yaml": None, "governance/council.yaml": "members:\n- login: bidji29\n",
                    "governance/guardians.yaml": "members:\n- login: alice\n"}, "the switch, then a guardian")
            self.assertEqual(bee.already_named(types.SimpleNamespace(root=root)), {"bidji29", "zoe", "alice"})
            commit({"governance/guardians.yaml": "membres:\n- pseudo: mallory\n"}, "French keys under the English name")
            self.assertIn("mallory", bee.already_named(types.SimpleNamespace(root=root)))  # either vocabulary, either path
            commit({"docs/x.md": "membres:\n- pseudo: eve\n"}, "another file")
            self.assertNotIn("eve", bee.already_named(types.SimpleNamespace(root=root)))  # only the two lists


# The forks' manifest before the switch: FILLED_MANIFEST with its French keys (english-names.md, section 6), a line at a time.
FRENCH_MANIFEST = re.sub(r"(?m)^( *)(task|user|model|summary|change|measurements|command|before|after|tested|untested|doubts|actual_size):",
                         lambda m: m[1] + {"task": "tache", "user": "utilisateur", "model": "modele", "summary": "resume", "change": "changement",
                                           "measurements": "mesures", "command": "commande", "before": "avant", "after": "apres", "tested": "teste",
                                           "untested": "non_teste", "doubts": "doutes", "actual_size": "taille_reelle"}[m[2]] + ":", FILLED_MANIFEST)
# A fork's verdict.json before F2 (bee/ci/verdict.py of minizBee): the French keys bee reads, and some it does not.
FRENCH_VERDICT = {"ci": "verte", "gain": 0.03, "metrique": "debit_compression_n6", "au_dela_du_bruit": True, "lignes_modifiees": 10,
                  "amorcage": True, "mesures": {"A": {"debit_compression_n6": 50.0}, "B": {"debit_compression_n6": 51.5}},
                  "degradations": {"memoire_max_ko": -0.02}, "instructions": {"instructions_n6": {"A": 100, "B": 90, "gain": 0.1}},
                  "base_juge": {"base": "a" * 40, "commit": "b" * 40, "regle": "point_de_depart"}, "etapes": {"juge": "succes"},
                  "juge": {"version": 2, "commun": "juge-v2", "sorties_comparees": 12, "constructions_suspectes": [{"type": "x", "detail": "y"}]},
                  "details": {"base": "c" * 40, "tete": "d" * 40, "origine_metrique": "tâche du registre"}}


class TestForkDocumentsRuche0145(BaseTest):
    """Until date D, a fork's manifest (manifests/, else manifestes/, else CONTRIBUTION.yaml) and its verdict.json are read in either
    vocabulary, one per document, and translated before any check; from D on, English only (plan, sections 6 and 10)."""

    def setUp(self):
        super().setUp()
        self.fork = pathlib.Path(self.temp.name) / "fork"
        self.fork.mkdir()
        (self.fork / "miniz_tdef.c").write_text("".join(f"ligne {i}\n" for i in range(100)), encoding="utf-8")
        git(self.fork, "init", "-q", "-b", "master")
        self.commit_fork()
        git(self.fork, "switch", "-qc", "task/miniz-0099")
        (self.fork / "miniz_tdef.c").write_text("".join(f"ligne {i}\n" for i in range(99)) + "ligne cent\n", encoding="utf-8")
        self.commit_fork()

    def commit_fork(self, files=None):
        for path, text in (files or {}).items():
            (self.fork / path).parent.mkdir(parents=True, exist_ok=True)
            (self.fork / path).write_text(text, encoding="utf-8") if text is not None else (self.fork / path).unlink()
        git(self.fork, "-c", "user.name=t", "-c", "user.email=t@t", "add", "-A")
        git(self.fork, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "travail", "--allow-empty")

    def check_fork(self):
        return self.bee("check-fork", "--task", "miniz-0099", "--base", "master", "--repo", str(self.fork))

    def after_d(self):
        return mock.patch.dict(os.environ, {"BEE_NOW": f"{bee.DATE_D}T00:00:00Z"})

    def test_the_keys_are_the_maps_and_date_d_is_a_date_at_the_earliest_2027(self):
        families = yaml.safe_load((ROOT / "tools/migration/names.yaml").read_text(encoding="utf-8"))["families"]
        for kind, family in (("manifest", "manifest"), ("verdict", "fork_verdict")):
            self.assertEqual(bee.FORK_KEYS[kind], {k: v for k, v in families[family]["keys"].items() if k != v}, kind)
        self.assertRegex(bee.DATE_D, r"\A[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")
        self.assertGreaterEqual(bee.DATE_D, "2027-01-01")

    def test_one_vocabulary_per_document_translated_until_date_d(self):
        english, french = yaml.safe_load(FILLED_MANIFEST), yaml.safe_load(FRENCH_MANIFEST)
        self.assertIn("non_teste", french)
        self.assertEqual(bee.fork_document("manifest", french, "m"), english)  # metric ids (avant, apres) kept
        self.assertIs(bee.fork_document("manifest", english, "m"), english)
        verdict = bee.fork_document("verdict", FRENCH_VERDICT, "v")
        self.assertEqual((verdict["changed_lines"], verdict["judge"]["outputs_compared"], verdict["judge_base"]["rule"], verdict["metric"]),
                         (10, 12, "point_de_depart", "debit_compression_n6"))
        for key in ("measurements", "degradations", "instructions", "steps", "details"):  # data-keyed, or not bee's: as written
            self.assertEqual(verdict[key], FRENCH_VERDICT[{"measurements": "mesures", "steps": "etapes"}.get(key, key)])
        for name, doc, kind in (("top", {**french, "user": "alice"}, "manifest"), ("nested", {**english, "agent": {"modele": "x"}}, "manifest"),
                                ("verdict", {**FRENCH_VERDICT, "changed_lines": 10}, "verdict")):
            with self.subTest(mixed=name), self.assertRaisesRegex(bee.BeeError, "one vocabulary per document"):
                bee.fork_document(kind, doc, "d")
        with self.after_d():
            for kind, doc in (("manifest", french), ("verdict", FRENCH_VERDICT)):
                with self.subTest(after_d=kind), self.assertRaisesRegex(bee.BeeError, f"read until {bee.DATE_D} only"):
                    bee.fork_document(kind, doc, "d")
            self.assertIs(bee.fork_document("manifest", english, "m"), english)
        self.assertEqual(bee.fork_document("manifest", ["a list"], "m"), ["a list"])  # left to the manifest's own checks

    def test_check_fork_reads_the_former_places_and_french_until_date_d(self):
        for name, files in (("manifestes/", {"manifestes/miniz-0099.yaml": FRENCH_MANIFEST}),
                            ("CONTRIBUTION.yaml in French", {"manifestes/miniz-0099.yaml": None, "CONTRIBUTION.yaml": FRENCH_MANIFEST}),
                            ("manifests/", {"CONTRIBUTION.yaml": None, "manifests/miniz-0099.yaml": FILLED_MANIFEST})):
            with self.subTest(name):
                self.commit_fork(files)
                code, text = self.check_fork()
                self.assertEqual(code, 0, text)
                self.assertIn("2 changed lines", text)  # the manifest's lines are not counted (R1)
        self.commit_fork({"manifests/miniz-0099.yaml": None, "manifestes/miniz-0099.yaml": FRENCH_MANIFEST})
        with self.after_d():
            code, text = self.check_fork()
        self.assertEqual(code, 1, text)
        self.assertIn("manifests/miniz-0099.yaml missing from the branch", text)
        for name, files, refusal in (
                ("two manifests", {"manifests/miniz-0099.yaml": FILLED_MANIFEST}, "two manifests for one task: keep manifests/miniz-0099.yaml only"),
                ("mixed", {"manifests/miniz-0099.yaml": None, "manifestes/miniz-0099.yaml": FRENCH_MANIFEST + "user: alice\n"},
                 "manifestes/miniz-0099.yaml: French keys (")):
            with self.subTest(name):
                self.commit_fork(files)
                code, text = self.check_fork()
                self.assertEqual(code, 1, text)
                self.assertIn(refusal, text)
                self.assertNotIn("missing from the branch", text)
        path = self.dir / "manifeste.yaml"
        path.write_text(FRENCH_MANIFEST, encoding="utf-8")
        self.assertEqual(self.bee("validate-manifest", str(path))[0], 0)
        with self.after_d():
            self.assertIn("French keys", self.bee("validate-manifest", str(path))[1])

    def test_record_verdict_reads_a_french_verdict_and_manifest_until_date_d(self):
        cid = self.submit_0099()
        verdict, manifest, path = self.dir / "verdict.json", self.dir / "manifeste.yaml", self.dir / f"contributions/miniz/{cid}.yaml"
        record = lambda *more: self.bee("record-verdict", cid, "--verdict", str(verdict), "--manifest", str(manifest), "--sha", "abc1234", *more)  # noqa: E731
        verdict.write_text(json.dumps(FRENCH_VERDICT), encoding="utf-8")
        manifest.write_text(FRENCH_MANIFEST, encoding="utf-8")
        code, text = record()
        self.assertEqual(code, 0, text)
        v = bee.read_yaml(path)["verdict"]
        self.assertEqual((v["ci"], v["changed_lines"], v["beyond_noise"], v["bootstrap"], v["declared_gap"], v["judge"]["outputs_compared"]),
                         ("green", 10, True, True, 0.07, 12))
        self.assertEqual(bee.read_yaml(path)["declared"]["model"], "modèle d'essai 1.0")
        self.valid_one()
        for word, ci in (("vert", "green"), ("succès", "green"), ("green_value", "red"), ("rouge", "red")):
            with self.subTest(ci=word):
                verdict.write_text(json.dumps({**FRENCH_VERDICT, "ci": word}), encoding="utf-8")
                self.assertEqual(record()[0], 0)
                self.assertEqual(bee.read_yaml(path)["verdict"]["ci"], ci)
        before = path.read_bytes()
        verdict.write_text(json.dumps({**FRENCH_VERDICT, "changed_lines": 10}), encoding="utf-8")
        code, text = record()
        self.assertEqual(code, 1, text)
        self.assertIn("one vocabulary per document", text)
        self.assertEqual(path.read_bytes(), before, "nothing written")
        with self.after_d():
            verdict.write_text(json.dumps(FRENCH_VERDICT), encoding="utf-8")
            self.assertIn(f"read until {bee.DATE_D} only", record()[1])
            self.assertEqual(path.read_bytes(), before, "nothing written")
            verdict.write_text(json.dumps({"ci": "green", "gain": 0.03, "metric": "debit_compression_n6", "changed_lines": 10}), encoding="utf-8")
            code, text = record()
            self.assertEqual(code, 0, text)
            self.assertIn("manifest ignored (task unreadable", text)  # French after D: ignored, as an unreadable manifest
            self.assertNotIn("declared_gap", bee.read_yaml(path)["verdict"])


class TestVerdictMetricRuche0145(BaseTest):
    """A green fork verdict that names its metric names the task's (plan, section 12, change 4): its gain is that metric's, or R4
    would judge on another one (a fork that misread the task finds no metric, null); from date D it must name it. Refused, nothing
    recorded, the head set aside. A red verdict is recorded as it is: it integrates nothing."""

    def test_a_verdict_measuring_another_metric_is_refused_and_the_tasks_one_recorded(self):
        cid = self.submit_0099()
        verdict, path = self.dir / "verdict.json", self.dir / f"contributions/miniz/{cid}.yaml"
        record = lambda sha: self.bee("record-verdict", cid, "--verdict", str(verdict), "--sha", sha)  # noqa: E731
        good = {"ci": "green", "gain": 0.03, "changed_lines": 10}
        for name, fields, said in (("another metric", {"metric": "memoire_max_ko"}, "memoire_max_ko"), ("none found", {"metric": None}, "None"),
                                   ("in French", {"metrique": "memoire_max_ko", "lignes_modifiees": 10}, "memoire_max_ko"),
                                   ("not a metric id", {"metric": "x\n::error::faux"}, "unreadable")):
            with self.subTest(name):
                verdict.write_text(json.dumps({**({"ci": "verte", "gain": 0.03} if "metrique" in fields else good), **fields}), encoding="utf-8")
                code, text = record("abc1234")
                self.assertEqual(code, 1, text)
                self.assertIn(f"verdict refused, {bee.VERDICT_WAIT['metric']} (the verdict's metric: {said}, the task's: debit_compression_n6)", text)
                self.assertNotIn("\n::error", text)
                rec = bee.read_yaml(path)
                self.assertNotIn("verdict", rec)
                self.assertEqual(rec["awaiting_verdict"], {"reason": "metric", "sha": "abc1234"})  # not judged again at this head
                self.valid_one()
        self.assertIn(bee.VERDICT_WAIT["metric"], self.bee("show", "miniz-0099")[1])
        for name, fields in (("the task's", {"metric": "debit_compression_n6"}), ("none named", {})):
            with self.subTest(name):
                verdict.write_text(json.dumps({**good, **fields}), encoding="utf-8")
                code, text = record("abc1235")
                self.assertEqual(code, 0, text)
                self.assertEqual(bee.read_yaml(path)["verdict"]["gain"], 0.03)

    def test_a_red_verdict_is_recorded_and_from_date_d_a_green_one_names_its_metric(self):
        cid = self.submit_0099()
        verdict, path = self.dir / "verdict.json", self.dir / f"contributions/miniz/{cid}.yaml"
        record = lambda sha: self.bee("record-verdict", cid, "--verdict", str(verdict), "--sha", sha)  # noqa: E731
        for name, fields in (("another metric", {"metric": "memoire_max_ko"}), ("none found", {"metric": None})):
            with self.subTest(red=name):
                verdict.write_text(json.dumps({"ci": "red", "failed_step": "tests", "changed_lines": 10, **fields}), encoding="utf-8")
                code, text = record("abc1234")
                self.assertEqual(code, 0, text)
                self.assertEqual({k: bee.read_yaml(path)["verdict"][k] for k in ("ci", "failed_step")}, {"ci": "red", "failed_step": "tests"})
        old = {"ci": "green", "gain": 0.03, "changed_lines": 10}  # no metric named: read before D (above), refused from D on
        verdict.write_text(json.dumps(old), encoding="utf-8")
        with mock.patch.dict(os.environ, {"BEE_NOW": f"{bee.DATE_D}T00:00:00Z"}):
            code, text = record("abc1235")
            self.assertEqual(code, 1, text)
            self.assertIn(f"verdict refused, {bee.VERDICT_WAIT['metric']} (the verdict's metric: absent, the task's: debit_compression_n6)", text)
            self.assertEqual(bee.read_yaml(path)["awaiting_verdict"], {"reason": "metric", "sha": "abc1235"})
            self.assertEqual(bee.read_yaml(path)["verdict"]["ci"], "red", "nothing recorded")
            verdict.write_text(json.dumps({**old, "metric": "debit_compression_n6"}), encoding="utf-8")
            code, text = record("abc1236")
            self.assertEqual(code, 0, text)
            self.assertEqual(bee.read_yaml(path)["verdict"]["ci"], "green")
            task = self.dir / "tasks/miniz/miniz-0099.yaml"  # a task without a metric (a test task): nothing to name
            bee.write_yaml(task, {**bee.read_yaml(task), "type": "test", "metric": None})
            verdict.write_text(json.dumps(old), encoding="utf-8")
            code, text = record("abc1237")
            self.assertEqual(code, 0, text)



class TestCheckMessagesRuche0146(unittest.TestCase):
    """tools/migration/check_messages.py (ruche-0146, ruche-0147): P1 restricted to message literals, on a toy file."""

    BASE = '''"""Doc en français."""
STATUS = "open"
MARK = "=== DONNÉES"


def f(n, path):
    """Doc."""
    if path.startswith(MARK):
        raise ValueError(f"{path} : {n} tâche(s) introuvable(s)")
    print("Tâche %s réservée" % n, "{id} prise".format(id=n), STATUS)
    return "introuvable"
'''

    def setUp(self):
        spec = importlib.util.spec_from_file_location("check_messages", ROOT / "tools" / "migration" / "check_messages.py")
        self.cm = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(self.cm)
        self.repo = pathlib.Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, self.repo, ignore_errors=True)
        (self.repo / "m.py").write_text(self.BASE, encoding="utf-8")
        for c in (["init", "-q"], ["add", "m.py"], ["-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "b"]):
            subprocess.run(["git", "-C", str(self.repo)] + c, check=True)

    def run_on(self, old, new, markers=False, prose=()):
        (self.repo / "m.py").write_text(self.BASE.replace(old, new), encoding="utf-8")
        return self.cm.check(self.repo, "HEAD", None, ["m.py"], markers, prose)

    def test_messages_reordered_interpolations_and_docstrings_pass(self):
        text = self.BASE.replace('f"{path} : {n} tâche(s) introuvable(s)"', 'f"{n} task(s) not found: {path}"')
        text = text.replace('"Tâche %s réservée"', '"Task %s reserved"').replace('"{id} prise"', '"{id} taken"')
        text = text.replace('"""Doc en français."""', '"""Doc in English."""')
        (self.repo / "m.py").write_text(text, encoding="utf-8")
        problems, counts = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
        self.assertEqual(problems, [])
        self.assertEqual((counts["m.py messages"], counts["docstrings"]), (3, 1))

    def test_a_name_literal_never_changes_unless_named_prose(self):
        problems, _ = self.run_on('STATUS = "open"', 'STATUS = "opened"')
        self.assertEqual(len(problems), 1)
        self.assertIn("a name literal changed", problems[0])
        self.assertEqual(len(self.run_on('return "introuvable"', 'return "not found"')[0]), 1)
        self.assertEqual(self.run_on('return "introuvable"', 'return "not found"', prose=("introuvable",))[0], [])

    def test_code_and_interpolations_never_change(self):
        for old, new in (('if path.startswith(MARK):', 'if path.endswith(MARK):'), ('{n} tâche(s)', '{n + 1} tâche(s)'),
                         ('return "introuvable"', 'return "introuvable" + ""')):
            problems, _ = self.run_on(old, new)
            self.assertEqual(len(problems), 1, new)
            self.assertIn("the code changed", problems[0])

    def test_a_compared_literal_needs_markers(self):
        problems, _ = self.run_on('MARK = "=== DONNÉES"', 'MARK = "=== DATA"')
        self.assertEqual(len(problems), 1)
        self.assertIn("compares text against", problems[0])
        self.assertEqual(self.run_on('MARK = "=== DONNÉES"', 'MARK = "=== DATA"', markers=True)[0], [])

    def test_a_template_keeps_its_fields(self):
        for old, new in (('"Tâche %s réservée"', '"Task reserved"'), ('"{id} prise"', '"{ident} taken"')):
            problems, _ = self.run_on(old, new)
            self.assertEqual(len(problems), 1, new)
            self.assertIn("fields changed", problems[0])

    def test_format_specs_conversions_and_percent_order(self):
        base = 'def g(n, x):\n    return "{n:,} élément(s), {x!r}".format(n=n, x=x), "%(a)s puis %(b)s" % {"a": n, "b": x}\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        for new, ok in (('"{n:,} item(s), {x!r}"', True), ('"{n} item(s), {x!r}"', False), ('"{n:,} item(s), {x!s}"', False),
                        ('"%(b)s after %(a)s"', True), ('"%(a)d then %(b)s"', False)):
            old = '"{n:,} élément(s), {x!r}"' if "{" in new else '"%(a)s puis %(b)s"'
            (self.repo / "m.py").write_text(base.replace(old, new), encoding="utf-8")
            problems, _ = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
            self.assertEqual(problems == [], ok, (new, problems))

    def test_markers_through_fstrings_locals_and_defaults(self):
        base = ('def g(s, n, m="erreur xx"):\n    marque = "attendu ici"\n    return s == f"Erreur {n}", marque in s, m in s, '
                's.startswith(f"=== FIN {n}")\n')
        base += 'class K:\n    def __init__(self):\n        self.marque = "au début"\n\n    def k(self, s):\n        return self.marque in s\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        for old, new in (('f"Erreur {n}"', 'f"Error {n}"'), ('"attendu ici"', '"expected here"'), ('"erreur xx"', '"error xx"'),
                         ('"au début"', '"at the start"'),
                         ('f"=== FIN {n}"', 'f"=== END {n}"')):
            (self.repo / "m.py").write_text(base.replace(old, new), encoding="utf-8")
            problems, _ = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
            self.assertEqual(len(problems), 1, new)
            self.assertIn("compares text against", problems[0])
            self.assertEqual(self.cm.check(self.repo, "HEAD", None, ["m.py"], True)[0], [], new)

    def test_letterless_literals_and_unreadable_heads(self):
        base = 'def g(x):\n    return " : ".join(x), "-"\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        (self.repo / "m.py").write_text(base.replace('" : "', '": "'), encoding="utf-8")
        problems, _ = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
        self.assertIn("without a letter", problems[0])
        self.assertEqual(self.cm.check(self.repo, "HEAD", None, ["m.py"], False, (" : ",))[0], [])
        (self.repo / "m.py").write_text("def g(:\n", encoding="utf-8")
        self.assertIn("does not parse", self.cm.check(self.repo, "HEAD", None, ["m.py"], False)[0][0])
        (self.repo / "m.py").unlink()
        self.assertIn("unreadable", self.cm.check(self.repo, "HEAD", None, ["m.py"], False)[0][0])

    def test_prose_names_fstrings_with_shown_holes_and_reads_a_list(self):
        base = 'def g(s, a, b):\n    return s.split(" | "), f"{a} | {b} introuvable", f"{a} manque"\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        (self.repo / "m.py").write_text(base.replace('f"{a} | {b} introuvable"', 'f"{a} / {b} not found"'), encoding="utf-8")
        problems, _ = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
        self.assertIn("compares text against", problems[0])  # a compared part, even a lone sign, is never waived silently
        self.assertEqual(self.cm.check(self.repo, "HEAD", None, ["m.py"], False, ("{…} | {…} introuvable",))[0], [])
        (self.repo / "m.py").write_text(base.replace('f"{a} manque"', 'f"{a}"'), encoding="utf-8")
        self.assertIn("name literal", self.cm.check(self.repo, "HEAD", None, ["m.py"], False)[0][0])
        listed = self.repo / "prose.json"
        listed.write_text(json.dumps(["{…} manque"]), encoding="utf-8")
        with mock.patch.object(self.cm, "ROOT", self.repo), contextlib.redirect_stdout(io.StringIO()), \
                contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(self.cm.main(["--base", "HEAD", "--prose-file", str(listed), "m.py"]), 0)
            self.assertEqual(self.cm.main(["--base", "HEAD", "m.py"]), 1)
            for bad in ("{", '{"a": 1}', None):
                if bad is None:
                    listed.unlink()
                else:
                    listed.write_text(bad, encoding="utf-8")
                with self.assertRaises(SystemExit):
                    self.cm.main(["--base", "HEAD", "--prose-file", str(listed), "m.py"])


    def test_inner_literals_with_inner_only(self):
        base = 'def g(xs, ok):\n    return f"{\' et \'.join(xs)} : {\'SERRÉ\' if ok else \'desserré\'}", f"{\', \'.join(xs)}"\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        new = base.replace("' et '", "' and '").replace("'SERRÉ'", "'TIGHT'").replace("'desserré'", "'loose'")
        (self.repo / "m.py").write_text(new, encoding="utf-8")
        self.assertIn("the code changed", self.cm.check(self.repo, "HEAD", None, ["m.py"], False)[0][0])
        self.assertEqual(len(self.cm.check(self.repo, "HEAD", None, ["m.py"], False, (), True)[0]), 2)  # one word: --prose
        problems, counts = self.cm.check(self.repo, "HEAD", None, ["m.py"], False, ("SERRÉ", "desserré"), True)
        self.assertEqual(problems, [])
        self.assertEqual(counts["m.py messages"], 3)
        (self.repo / "m.py").write_text(new.replace("', '", "'; '"), encoding="utf-8")
        self.assertIn("without a letter", self.cm.check(self.repo, "HEAD", None, ["m.py"], False, ("SERRÉ", "desserré"), True)[0][0])
        (self.repo / "m.py").write_text(new.replace("if ok", "if not ok"), encoding="utf-8")
        self.assertIn("the code changed", self.cm.check(self.repo, "HEAD", None, ["m.py"], False, ("SERRÉ", "desserré"), True)[0][0])
        swap = 'def f(a, b):\n    return f"{a(\'un mot\')} {b(\'deux mots\')}"\n'
        (self.repo / "m.py").write_text(swap, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "s"], check=True)
        (self.repo / "m.py").write_text(swap.replace("'un mot'", "'X'").replace("'deux mots'", "'un mot'").replace("'X'", "'deux mots'"),
                                        encoding="utf-8")
        self.assertIn("moved or swapped", self.cm.check(self.repo, "HEAD", None, ["m.py"], False, (), True)[0][0])  # a swap

    def test_a_docstring_may_change_its_braces(self):
        base = 'def g():\n    """{utilisateur, depuis} : une liste."""\n    return "{x}".format(x=1)\n'
        (self.repo / "m.py").write_text(base, encoding="utf-8")
        subprocess.run(["git", "-C", str(self.repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "g"], check=True)
        (self.repo / "m.py").write_text(base.replace("{utilisateur, depuis} : une liste", "a list of {user, since}"), encoding="utf-8")
        problems, counts = self.cm.check(self.repo, "HEAD", None, ["m.py"], False)
        self.assertEqual((problems, counts["docstrings"]), ([], 1))
        (self.repo / "m.py").write_text(base.replace('"{x}"', '"{y}"'), encoding="utf-8")
        self.assertIn("fields changed", self.cm.check(self.repo, "HEAD", None, ["m.py"], False)[0][0])  # a template still may not

